// Poland, hand-written content (tools/content/batches/add_pl1.py, 2026-11-22).
window.RA_DATA = window.RA_DATA || {};
window.RA_DATA.lines = [
  { id: "pl-pan-tadeusz-1", book_id: "pl-pan-tadeusz", place_ids: ["pl-jasna-gora"], location: "Book I, lines 5–7", location_zh: "第一卷，第 5–7 行", text_orig: "Panno święta, co Jasnej bronisz Częstochowy\nI w Ostrej świecisz Bramie! Ty, co gród zamkowy\nNowogródzki ochraniasz z jego wiernym ludem!", highlight_orig: ["Częstochowy"], text_en: "Holy Virgin, who guard bright Częstochowa and shine in the Ostra Gate! You who shelter the castle town of Nowogródek with its faithful people!", highlight_en: ["Częstochowa"], text_zh: "圣洁的童贞女啊，你守护着光明山上的琴斯托霍瓦，在尖门之上放射光辉！你庇护着诺沃格鲁代克的城堡和城中忠诚的百姓！", highlight_zh: ["琴斯托霍瓦"], translation: "own", status: "draft", checked: "Polish Wikisource, Pan Tadeusz (wyd. 1921)/Księga pierwsza: Gospodarstwo, 2026-11-22" },
  { id: "pl-pan-tadeusz-2", book_id: "pl-pan-tadeusz", place_ids: ["pl-bialowieza"], location: "Book IV, lines 1–4", location_zh: "第四卷，第 1–4 行", text_orig: "Rówienniki litewskich wielkich kniaziów, drzewa\nBiałowieży, Świtezi, Ponar, Kuszelewa!\nKtórych cień spadał niegdyś na koronne głowy\nGroźnego Witenesa, wielkiego Mindowy,", highlight_orig: ["Białowieży"], text_en: "Trees coeval with the grand dukes of Lithuania, trees of Białowieża, Świteź, Ponary, Kuszelewo! whose shade once fell on the crowned heads of dread Witenes and great Mindowe,", highlight_en: ["Białowieża"], text_zh: "与立陶宛历代大公同龄的树木啊，比亚沃维耶扎、希维泰什、波纳雷、库舍莱沃的树木！你们的浓荫曾落在威严的维泰尼斯和伟大的明道加斯戴着王冠的头上，", highlight_zh: ["比亚沃维耶扎"], translation: "own", status: "draft", checked: "Polish Wikisource, Pan Tadeusz (wyd. 1921)/Księga czwarta: Dyplomatyka i łowy, 2026-11-22" },
  { id: "pl-kordian-1", book_id: "pl-kordian", place_ids: ["pl-zamek-krolewski"], location: "Act III, Scene 1, stage direction", location_zh: "第三幕第一场，舞台说明", text_orig: "Plac przed zamkiem królewskim w Warszawie, okna dokolnych domów przystrojone kobiercami, pełne widzów. – Wielkie rusztowanie, czerwoném suknem nakryte, zalega większą część placu – na niém siedzą rzędami przystrojone kobiety... Najbliżéj widza kolumna Zygmunta, na podstawie lud zasiadł... Ludzie różnego stanu stoją dokoła i patrząc na zamek rozmawiają.", highlight_orig: ["zamkiem królewskim"], text_en: "The square before the Royal Castle in Warsaw; the windows of the houses around are hung with carpets and full of spectators. – A great scaffold covered with red cloth fills most of the square – on it women in their finery sit in rows... Nearest the audience stands Sigismund's Column, with the common people seated on its base... People of every rank stand about, looking at the castle and talking.", highlight_en: ["Royal Castle"], text_zh: "华沙王宫城堡前的广场，四周房屋的窗口挂着毯子，挤满了看热闹的人。——一座蒙着红布的大看台占去了广场的大半——盛装的妇女一排排坐在上面……离观众最近的是西吉斯蒙德圆柱，百姓坐在柱基上……各色人等站在四周，望着城堡交谈。", highlight_zh: ["王宫城堡"], translation: "own", status: "draft", checked: "Polish Wikisource, Kordian/Akt III, 2026-11-22" },
  { id: "pl-balladyna-1", book_id: "pl-balladyna", place_ids: ["pl-goplo"], location: "Act I, Scene 2", location_zh: "第一幕第二场", text_orig: "Inna część lasu — widać jezioro Gopło.\nSKIERKA I CHOCHLIK (wchodzą.)\nSKIERKA.\nGdzie jest Goplana, nasza królowa?\nCHOCHLIK.\nSpi jeszcze w Gople.", highlight_orig: ["Gopło"], text_en: "Another part of the forest — Lake Gopło can be seen.\nSKIERKA AND CHOCHLIK (enter.)\nSKIERKA.\nWhere is Goplana, our queen?\nCHOCHLIK.\nStill asleep in Gopło.", highlight_en: ["Gopło"], text_zh: "森林的另一处——可以望见戈普沃湖。\n斯凯尔卡和霍赫利克（上。）\n斯凯尔卡：\n我们的女王戈普拉娜在哪儿？\n霍赫利克：\n还在戈普沃湖里睡着呢。", highlight_zh: ["戈普沃湖"], translation: "own", status: "draft", checked: "Polish Wikisource, Balladyna/Akt pierwszy, 2026-11-22" },
  { id: "pl-stara-basn-1", book_id: "pl-stara-basn", place_ids: ["pl-goplo"], location: "Volume III, Chapter 1", location_zh: "第三卷第一章", text_orig: "Ciągnęli kmiecie ze wszech stron nad Gopło, jechali i Leszki ponuro patrząc, ze strachem w sercach, ale nie chcąc ustąpić.", highlight_orig: ["Gopło"], text_en: "From every side the freeholders made their way to Gopło; the Leszeks rode too, grim-faced, with fear in their hearts, but unwilling to give way.", highlight_en: ["Gopło"], text_zh: "自由农从四面八方向戈普沃湖赶来；莱谢克家族的人也骑马来了，脸色阴沉，心里害怕，却不肯退让。", highlight_zh: ["戈普沃湖"], translation: "own", status: "draft", checked: "Polish Wikisource, Stara baśń/Tom III/I, 2026-11-22" },
  { id: "pl-fraszki-1", book_id: "pl-fraszki", place_ids: ["pl-czarnolas"], location: "'On the Linden Tree', lines 1–4", location_zh: "《咏椴树》第 1–4 行", text_orig: "Gościu, siądź pod mym liściem a odpocznij sobie,\nNie dojdzie cię tu słońce, przyrzekam ja tobie,\nChoć się najwyżej wzbije, a proste promienie\nŚciągną pod swoje drzewa rozstrzelane cienie.", highlight_orig: ["pod mym liściem"], text_en: "Guest, sit down beneath my leaves and take your rest; the sun will not reach you here, I promise you, though it climb its highest and its straight rays draw the scattered shadows in beneath the trees.", highlight_en: ["beneath my leaves"], text_zh: "客人啊，请坐在我的叶荫下歇一歇，我向你保证，太阳照不到这里，哪怕它升到最高处，直射的光线把四散的树影都收拢到树下。", highlight_zh: ["我的叶荫下"], translation: "own", status: "draft", checked: "Polish Wikisource, Ziemia polska w pieśni/Na lipę, 2026-11-22" },
  { id: "pl-lalka-1", book_id: "pl-lalka", place_ids: ["pl-krakowskie-przedmiescie"], location: "Volume I, Chapter 1", location_zh: "第一卷第一章", text_orig: "W początkach r. 1878, kiedy świat polityczny zajmował się pokojem san-stefańskim, wyborem nowego papieża, albo szansami europejskiej wojny, warszawscy kupcy, tudzież inteligencya pewnej okolicy Krakowskiego Przedmieścia, niemniej gorąco interesowała się przyszłością galanteryjnego sklepu pod firmą J. Mincel i S. Wokulski.", highlight_orig: ["Krakowskiego Przedmieścia"], text_en: "At the beginning of 1878, when the political world was occupied with the peace of San Stefano, the election of a new pope, or the chances of a European war, the merchants of Warsaw, and likewise the educated public of a certain part of Krakowskie Przedmieście, were no less warmly interested in the future of the fancy-goods shop trading as J. Mincel and S. Wokulski.", highlight_en: ["Krakowskie Przedmieście"], text_zh: "1878 年初，政界正忙着谈论圣斯特凡诺和约、新教皇的选举或欧洲开战的可能，华沙的商人们，还有克拉科夫郊区街某一带的知识界，却同样热切地关心着“J. 明采尔与 S. 沃库尔斯基”这家时髦杂货店的前途。", highlight_zh: ["克拉科夫郊区街"], translation: "own", status: "draft", checked: "Polish Wikisource, Lalka (Prus)/Tom I/I, 2026-11-22" },
  { id: "pl-lalka-2", book_id: "pl-lalka", place_ids: ["pl-powisle"], location: "Volume I, Chapter 8", location_zh: "第一卷第八章", text_orig: "Wokulski doszedł do brzegu Wisły i zdumiał się. Na kilkumorgowej przestrzeni wznosił się tu pagórek najobrzydliwszych śmieci, cuchnących, nieomal ruszających się pod słońcem, a o kilkadziesiąt kroków dalej, leżały zbiorniki wody, którą piła Warszawa.", highlight_orig: ["Wisły"], text_en: "Wokulski came to the bank of the Vistula and stopped in amazement. Over several acres there rose a hill of the most loathsome refuse, stinking, almost stirring in the sun, and a few dozen paces further on lay the reservoirs of the water that Warsaw drank.", highlight_en: ["Vistula"], text_zh: "沃库尔斯基走到维斯瓦河岸边，愣住了。几亩大的一片地上，隆起一座最令人作呕的垃圾山，臭气熏天，在太阳底下几乎在蠕动，而几十步开外，就是华沙人饮用水的蓄水池。", highlight_zh: ["维斯瓦河"], translation: "own", status: "draft", checked: "Polish Wikisource, Lalka (Prus)/Tom I/VIII, 2026-11-22" },
  { id: "pl-lalka-3", book_id: "pl-lalka", place_ids: ["pl-lazienki"], location: "Volume I, Chapter 11", location_zh: "第一卷第十一章", text_orig: "Znalazłszy się w Łazienkach, wyskakiwał z powozu i biegł nad sadzawkę, gdzie zazwyczaj spacerowała hrabina, lubiąca karmić łabędzie. Przychodził zawczasu, a wtedy padał gdzieś na ławkę, zalany zimnym potem i siedział, bez ruchu, z oczyma skierowanemi w stronę pałacu, zapominając o świecie.", highlight_orig: ["Łazienkach"], text_en: "Once in the Łazienki park he would leap from the carriage and run to the pond where the countess, who liked to feed the swans, usually walked. He came too early, and then he would drop onto a bench somewhere, bathed in cold sweat, and sit motionless, his eyes turned towards the palace, forgetting the world.", highlight_en: ["Łazienki"], text_zh: "一到瓦津基公园，他就跳下马车，跑向池塘边——喜欢喂天鹅的伯爵夫人通常在那里散步。他总是来得太早，于是随便倒在一张长椅上，浑身冷汗，一动不动地坐着，眼睛望着宫殿的方向，忘了整个世界。", highlight_zh: ["瓦津基公园"], translation: "own", status: "draft", checked: "Polish Wikisource, Lalka (Prus)/Tom I/XI, 2026-11-22" },
  { id: "pl-krzyzacy-1", book_id: "pl-krzyzacy", place_ids: ["pl-tyniec"], location: "Part 1, Chapter 1", location_zh: "第一部第一章", text_orig: "W Tyńcu, w gospodzie pod „Lutym Turem“, należącej do opactwa, siedziało kilku ludzi, słuchając opowiadania wojaka bywalca, który z dalekich stron przybywszy, prawił im o przygodach, jakich na wojnie i w podróży doznał.", highlight_orig: ["Tyńcu"], text_en: "At Tyniec, in the inn 'Under the Savage Aurochs', which belonged to the abbey, a few men sat listening to the tale of a soldier who had seen the world and who, come from distant parts, was telling them of the adventures he had met with in war and on the road.", highlight_en: ["Tyniec"], text_zh: "在蒂涅茨，修道院名下的“猛野牛”客店里，坐着几个人，正听一位见过世面的武士讲故事；他从远方来，给他们讲自己在战场上和旅途中的种种遭遇。", highlight_zh: ["蒂涅茨"], translation: "own", status: "draft", checked: "Polish Wikisource, Krzyżacy (Sienkiewicz, 1900)/Część pierwsza/I, 2026-11-22" },
  { id: "pl-krzyzacy-2", book_id: "pl-krzyzacy", place_ids: ["pl-malbork"], location: "Part 9, Chapter 6", location_zh: "第九部第六章", text_orig: "A przedewszystkiem sam widok Malborga mógł przejąć trwogą serce każdego Polaka, albowiem z twierdzą ową licząc Wysoki zamek, Średni i Przedzamcze, żadna inna w całym świecie nie mogła się nawet w przybliżeniu porównać.", highlight_orig: ["Malborga"], text_en: "And above all the mere sight of Malbork could strike dread into the heart of any Pole, for with that fortress, counting the High Castle, the Middle Castle and the Outer Bailey, no other in the whole world could even approximately compare.", highlight_en: ["Malbork"], text_zh: "尤其是，单是马尔堡的景象就足以让任何一个波兰人心生恐惧，因为这座要塞连同高堡、中堡和外堡在内，全世界没有哪一座能勉强同它相比。", highlight_zh: ["马尔堡"], translation: "own", status: "draft", checked: "Polish Wikisource, Krzyżacy (Sienkiewicz, 1900)/Część dziewiąta/VI, 2026-11-22" },
  { id: "pl-krzyzacy-3", book_id: "pl-krzyzacy", place_ids: ["pl-grunwald"], location: "Part 11, Chapter 5", location_zh: "第十一部第五章", text_orig: "W środku owej przestrzeni, wznoszącej się ku zachodowi łagodnie w górę, zieleniły się łęgi Grunwaldu, a nieco w dali szarzały słomiane dachy i smutne ugory Tannenberga.", highlight_orig: ["Grunwaldu"], text_en: "In the middle of that expanse, which rose gently towards the west, the water-meadows of Grunwald showed green, and a little further off the thatched roofs and sad fallows of Tannenberg showed grey.", highlight_en: ["Grunwald"], text_zh: "这片向西缓缓升高的原野中央，格伦瓦尔德的河滩草地一片青绿，稍远处是坦能堡灰蒙蒙的茅草屋顶和凄凉的休耕地。", highlight_zh: ["格伦瓦尔德"], translation: "own", status: "draft", checked: "Polish Wikisource, Krzyżacy (Sienkiewicz, 1900)/Część jedenasta/V, 2026-11-22" },
  { id: "pl-potop-1", book_id: "pl-potop", place_ids: ["pl-jasna-gora"], location: "Volume III, Chapter 16", location_zh: "第三卷第十六章", text_orig: "Kraj cały był jako okręt pogrążony już w otchłani, a jeno ów klasztor sterczał jeszcze jak koniec masztu nad falami.", highlight_orig: ["klasztor"], text_en: "The whole country was like a ship already sunk in the abyss, and only that monastery still stood out like the tip of a mast above the waves.", highlight_en: ["monastery"], text_zh: "整个国家像一艘已沉入深渊的船，只有那座修道院还像桅杆的尖顶一样露在波涛之上。", highlight_zh: ["修道院"], translation: "own", status: "draft", checked: "Polish Wikisource, Potop (Sienkiewicz)/Tom III/Rozdział XVI, 2026-11-22" },
  { id: "pl-chlopi-1", book_id: "pl-chlopi", place_ids: ["pl-lipce"], location: "Spring, Chapter 1", location_zh: "《春》第一章", text_orig: "Aż dopiero, gdy sygnaturka zaświegotała na Lipieckim kościele, kiej ten ptaszek, zwołujący na modlitwę, ocknęła stara znagła, padając na kolana.", highlight_orig: ["Lipieckim"], text_en: "Only when the little bell began to twitter on Lipce church, like a small bird calling to prayer, did the old woman suddenly come to herself and fall on her knees.", highlight_en: ["Lipce"], text_zh: "直到利普采教堂上的小钟像一只召唤人祈祷的小鸟似的啁啾起来，老太婆才猛然回过神，双膝跪下。", highlight_zh: ["利普采"], translation: "own", status: "draft", checked: "Polish Wikisource, Chłopi (Reymont)/Wiosna/I, 2026-11-22" },
  { id: "pl-ziemia-1", book_id: "pl-ziemia-obiecana", place_ids: ["pl-palac-poznanskiego"], location: "Volume I, Chapter 1", location_zh: "第一卷第一章", text_orig: "Łódź się budziła.\nPierwszy wrzaskliwy świst fabryczny rozdarł ciszę wczesnego poranku, a za nim we wszystkich stronach miasta zaczęły się zrywać coraz zgiełkliwiej inne i darły się chrapliwymi, niesfornymi głosami, niby chór potwornych kogutów, piejących metalowymi gardzielami hasło do pracy.", highlight_orig: ["Łódź"], text_en: "Łódź was waking.\nThe first shrill factory whistle tore the silence of the early morning, and after it, in every part of the city, others began to start up ever more noisily and screamed in hoarse, unruly voices, like a choir of monstrous cocks crowing the call to work from metal throats.", highlight_en: ["Łódź"], text_zh: "罗兹正在醒来。\n第一声尖厉的工厂汽笛撕破了清晨的寂静，接着，全城各处别的汽笛也一个比一个喧闹地响起来，用嘶哑、不听管束的嗓音嚎叫，像一群怪物般的公鸡，用金属的喉咙啼出上工的号令。", highlight_zh: ["罗兹"], translation: "own", status: "draft", checked: "Polish Wikisource, Ziemia Obiecana (Reymont, 1899)/Tom pierwszy/Rozdział I (paragraph indent dropped), 2026-11-22" },
  { id: "pl-ziemia-2", book_id: "pl-ziemia-obiecana", place_ids: ["pl-piotrkowska"], location: "Volume I, Chapter 1", location_zh: "第一卷第一章", text_orig: "Deszcz mrzył bezustannie i zacinał skośnie, aż do pół okien małych domków, co w tym końcu Piotrkowskiej ulicy stały gęsto przy sobie, gdzieniegdzie tylko jakby rozepchnięte olbrzymem fabrycznym lub wspaniałym pałacem fabrykanta.", highlight_orig: ["Piotrkowskiej ulicy"], text_en: "The rain drizzled without stopping and slanted in, reaching halfway up the windows of the little houses that stood close together at this end of Piotrkowska Street, pushed apart only here and there by a giant of a factory or a manufacturer's splendid palace.", highlight_en: ["Piotrkowska Street"], text_zh: "雨下个不停，斜斜地打过来，直打到小房子的半截窗户上；在彼得科夫斯卡大街的这一头，这些小房子一幢挨着一幢，只是偶尔被一座巨人般的工厂或厂主的华丽宫殿挤开。", highlight_zh: ["彼得科夫斯卡大街"], translation: "own", status: "draft", checked: "Polish Wikisource, Ziemia Obiecana (Reymont, 1899)/Tom pierwszy/Rozdział I (a double space written as one), 2026-11-22" },
  { id: "pl-syzyfowe-1", book_id: "pl-syzyfowe-prace", place_ids: ["pl-kielce"], location: "Chapter 3", location_zh: "第三章", text_orig: "Na dolnym korytarzu gimnazjum klasycznego w Klerykowie znajdowało się mnóstwo osób. Byli tam urzędnicy, szlachta, księża, przemysłowcy, a nawet zamożniejsi chłopi. Cały ten tłum stanowił w owej chwili jedną kategorję: rodziców.", highlight_orig: ["Klerykowie"], text_en: "In the lower corridor of the classical gymnasium in Kleryków there was a great crowd of people. There were officials, gentry, priests, tradesmen, and even the better-off peasants. At that moment the whole crowd made up a single category: parents.", highlight_en: ["Kleryków"], text_zh: "克莱里科夫古典中学楼下的走廊里挤满了人。有官吏、乡绅、神父、工商业者，甚至还有富裕些的农民。此刻这一大群人只属于同一类：家长。", highlight_zh: ["克莱里科夫"], translation: "own", status: "draft", checked: "Polish Wikisource, Syzyfowe prace/III, 2026-11-22" },
  { id: "pl-przedwiosnie-1", book_id: "pl-przedwiosnie", place_ids: ["pl-belweder"], location: "Part 3, last pages", location_zh: "第三部结尾", text_orig: "Tego dnia właśnie od Nowego Światu, przez plac Trzech Krzyżów ciągnęła wielka manifestacya robotnicza w stronę Belwederu.", highlight_orig: ["Belwederu"], text_en: "On that very day, from Nowy Świat across Three Crosses Square, a great workers' demonstration was moving towards the Belweder.", highlight_en: ["Belweder"], text_zh: "就在这一天，一支浩大的工人游行队伍从新世界街出发，穿过三十字广场，向贝尔维德宫走去。", highlight_zh: ["贝尔维德宫"], translation: "own", status: "draft", checked: "Polish Wikisource, Przedwiośnie (Żeromski)/Część trzecia, 2026-11-22" },
  { id: "pl-puszcza-1", book_id: "pl-puszcza-jodlowa", place_ids: ["pl-swiety-krzyz"], location: "Opening", location_zh: "开篇", text_orig: "W uszach moich trwa szum twój, lesie dzieciństwa i młodości, — choć tyle już lat nie dano mi go słyszeć na jawie! Przebiegam w marzeniu wyniosłe góry — Łysicę, Łysiec, Strawczaną, Bukową, Klonową, Stróżnę, — góry moje domowe — Radostową i Kamień, — oraz wszystkie dalekie siostrzyce.", highlight_orig: ["Łysiec"], text_en: "Your rustling is still in my ears, forest of my childhood and youth — though for so many years I have not been allowed to hear it waking! In my dreams I range the lofty mountains — Łysica, Łysiec, Strawczana, Bukowa, Klonowa, Stróżna — my own home mountains — Radostowa and Kamień — and all their distant sisters.", highlight_en: ["Łysiec"], text_zh: "你的涛声还在我耳边回响，我童年和青年时代的森林啊——虽然这么多年我再也没能在醒着的时候听到它！我在梦想中跑遍那些高高的山——韦希察山、韦希耶茨山、斯特拉夫恰纳山、布科瓦山、克洛诺瓦山、斯特鲁日纳山——我家门口的山——拉多斯托瓦山和卡缅山——还有它们远方所有的姊妹。", highlight_zh: ["韦希耶茨山"], translation: "own", status: "draft", checked: "Polish Wikisource, Puszcza jodłowa, 2026-11-22" },
  { id: "pl-wesele-1", book_id: "pl-wesele", place_ids: ["pl-bronowice"], location: "Act I, the set", location_zh: "第一幕，布景说明", text_orig: "Noc Listopadowa; w chacie, w świetlicy. Izba wybielona siwo, prawie błękitna, jednym szarawym tonem pół-błękitu obejmująca i sprzęty i ludzi, którzy się przez nią przesuną.", highlight_orig: ["chacie"], text_en: "A November night; in a peasant cottage, in the best room. The room is whitewashed a grey that is almost blue, a single greyish half-blue tone that takes in both the furniture and the people who will pass through it.", highlight_en: ["cottage"], text_zh: "十一月的夜晚；农舍里，正屋中。屋子刷成发灰的白色，近乎淡蓝，一种灰蒙蒙的半蓝色调把家具和将从屋里走过的人都罩在里面。", highlight_zh: ["农舍"], translation: "own", status: "draft", checked: "Polish Wikisource, Wesele (Wyspiański)/Akt I, 2026-11-22" },
  { id: "pl-akropolis-1", book_id: "pl-akropolis", place_ids: ["pl-wawel"], location: "Act I, opening lines", location_zh: "第一幕开头", text_orig: "Poszli i na kościele ostawili dymu\npowłoczną chmurę; — oplotła kolumny.\nPieśniarze, co śpiewali pieśni Rzymu,\npokłony bijąc u ołtarza-trumny.", highlight_orig: ["kościele"], text_en: "They have gone, and in the church they have left a trailing cloud of smoke; — it has wound about the columns. The singers who sang the songs of Rome, bowing low before the coffin-altar.", highlight_en: ["church"], text_zh: "他们走了，在教堂里留下一片拖曳的烟云；——它缠绕着廊柱。那些唱罗马圣歌的歌者，方才还在棺椁祭坛前深深叩拜。", highlight_zh: ["教堂"], translation: "own", status: "draft", checked: "Polish Wikisource, Akropolis/Akt pierwszy, 2026-11-22" },
  { id: "pl-w-tatrach-1", book_id: "pl-w-tatrach", place_ids: ["pl-morskie-oko"], location: "'Morskie Oko', I, lines 1–4", location_zh: "《海眼湖》其一，第 1–4 行", text_orig: "Ponad płaszczami borów, ściśnięte zaporą\nŚcian olbrzymich, co w koło ze sobą się zwarły,\nCiemne wody rozlewa posępne jezioro,\nOdzwierciedlając w łonie głazów świat zamarły.", highlight_orig: ["jezioro"], text_en: "Above the cloaks of the forests, hemmed in by a barrier of giant walls that have closed in a ring, a sombre lake spreads its dark waters, mirroring in its depths a dead world of boulders.", highlight_en: ["lake"], text_zh: "在森林的披风之上，被合围成一圈的巨壁紧紧锁住，一座阴郁的湖铺开它幽暗的水，湖心映出一个死寂的巨石世界。", highlight_zh: ["湖"], translation: "own", status: "draft", checked: "Polish Wikisource, Morskie Oko (Asnyk, wyd. 1898), 2026-11-22" },
  { id: "pl-tetmajer-1", book_id: "pl-tetmajer-poezje", place_ids: ["pl-czarny-staw"], location: "'Melody of the Night Mists', lines 1–2", location_zh: "《夜雾的旋律》第 1–2 行", text_orig: "(Nad Czarnym Stawem Gąsienicowym).\nCicho, cicho, nie budźmy śpiącej wody w kotlinie,\nLekko z wiatrem pląsajmy po przestworów głębinie...", highlight_orig: ["Czarnym Stawem Gąsienicowym"], text_en: "(Above Czarny Staw Gąsienicowy.)\nHush, hush, let us not wake the water sleeping in the hollow, lightly let us dance with the wind over the deeps of the open air...", highlight_en: ["Czarny Staw Gąsienicowy"], text_zh: "（在加雄尼措瓦黑湖之上。）\n轻些，轻些，别惊醒山坳里沉睡的水，让我们随风轻舞，掠过长空的深处……", highlight_zh: ["加雄尼措瓦黑湖"], translation: "own", status: "draft", checked: "Polish Wikisource, Melodya mgieł nocnych (Tetmajer, wyd. 1901), 2026-11-22" },
  { id: "pl-eichendorff-1", book_id: "pl-eichendorff-gedichte", place_ids: ["pl-lubowice"], location: "'Abschied', first stanza", location_zh: "《告别》第一节", text_orig: "Im Walde bei Lubowitz.\nO Thäler weit, o Höhen,\nO schöner, grüner Wald,\nDu meiner Lust und Wehen\nAndächt’ger Aufenthalt!\nDa draußen, stets betrogen,\nSaust die geschäft’ge Welt,\nSchlag’ noch einmal die Bogen\nUm mich, du grünes Zelt!", highlight_orig: ["Lubowitz"], text_en: "In the forest near Lubowitz.\nO valleys wide, o heights, o fair green wood, devout abode of my joy and my sorrows! Out there, forever cheated, the busy world roars by; once more throw your arches round me, you green tent!", highlight_en: ["Lubowitz"], text_zh: "在卢博维茨附近的森林里。\n啊，宽阔的山谷，啊，高冈，啊，美丽青翠的森林，你是我欢乐与悲愁的虔诚居所！外面，那永远受骗的忙碌世界呼啸而过；再一次用你的拱顶把我环抱吧，你这绿色的帐幕！", highlight_zh: ["卢博维茨"], translation: "own", status: "draft", checked: "German Wikisource, Abschied (Eichendorff), 2026-11-22" },
  { id: "pl-svejk-1", book_id: "cz-svejk", place_ids: ["pl-sanok"], location: "Book III, Chapter 4", location_zh: "第三卷第四章", text_orig: "Objevilo se, když se přijelo do Sanoku, že vlastně na tom voze s polní kuchyní jedenáctky, kde prděl blahem nasycený Baloun, měli celkem pravdu, že bude večeře, a dokonce kromě večeře že tam bude rozdáván nějaký komisárek za všechny ty dny, kdy nedostal batalión ničeho.", highlight_orig: ["Sanoku"], text_en: "When they reached Sanok it turned out that the men on the wagon with the Eleventh's field kitchen, where the well-fed Baloun was farting with bliss, had on the whole been right: there would be supper, and besides supper some army bread would be handed out for all the days when the battalion had got nothing.", highlight_en: ["Sanok"], text_zh: "到了萨诺克才发现，十一连炊事车上的人——吃饱了的巴伦正在车上惬意地放着屁——大体上没说错：晚饭是有的，而且除了晚饭，还要补发军用面包，把全营一无所得的那些天都补上。", highlight_zh: ["萨诺克"], translation: "own", status: "draft", checked: "Czech Wikisource, Osudy dobrého vojáka Švejka za světové války/Marschieren marsch!, 2026-11-22" },
  { id: "pl-conrad-1", book_id: "pl-notes-life-letters", place_ids: ["pl-mariacki"], location: "'Poland Revisited', Part III", location_zh: "《重访波兰》第三节", text_en: "To our right the unequal massive towers of St. Mary's Church soared aloft into the ethereal radiance of the air, very black on their shaded sides, glowing with a soft phosphorescent sheen on the others.", highlight_en: ["St. Mary's Church"], translation: "original", text_zh: "在我们右边，圣母教堂那两座高矮不一的粗壮塔楼高耸入空中缥缈的清辉，背光的一面漆黑，另一面泛着柔和的磷光。", highlight_zh: ["圣母教堂"], status: "draft", checked: "English Wikisource, Notes on Life and Letters (line breaks and double spaces written as single spaces), 2026-11-22" },
  { id: "pl-ocalenie-s1", kind: "scene", book_id: "pl-ocalenie", place_ids: ["pl-plac-krasinskich"], location: "'Campo dei Fiori'", location_zh: "《鲜花广场》", text_en: "The poem begins in Rome, on the square where Giordano Bruno was burned and where, the moment the fire died, the market went on. Then it turns to Warsaw on a fine spring evening: by the carousel on Krasiński Square couples ride up into the air to cheerful music while, behind the ghetto wall, the houses burn and the wind carries the smuts over. Miłosz's subject is the loneliness of the dying, and the poet who will speak of it later.", text_zh: "诗从罗马写起：布鲁诺被烧死的那座广场上，火刚熄，集市就照常开张。接着转到一个晴朗春夜的华沙：克拉辛斯基广场的旋转木马旁，一对对男女随着欢快的音乐升上半空，而隔离区的墙后面，房子在燃烧，风把黑色的灰烬吹过来。米沃什写的是垂死者的孤独，以及日后将要说起这一切的诗人。", highlight_en: ["Krasiński Square"], highlight_zh: ["克拉辛斯基广场"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Czes%C5%82aw_Mi%C5%82osz" },
  { id: "pl-pamietnik-s1", kind: "scene", book_id: "pl-pamietnik-powstania", place_ids: ["pl-stare-miasto"], location: "August 1944", location_zh: "1944 年 8 月", text_en: "Białoszewski tells the sixty-three days as a civilian who never held a gun: running from cellar to cellar, queueing for water, counting the minutes between bombs, carrying the wounded, losing track of the date. He wrote it more than twenty years later in the broken, breathless speech of someone still telling it aloud. From the Old Town he escapes, like thousands of others, through the sewers.", text_zh: "比亚沃舍夫斯基以一个从没拿过枪的平民的身份讲这六十三天：从一个地下室跑到另一个地下室，排队打水，数着两次轰炸之间隔了几分钟，抬伤员，记不清日子。二十多年后他才把它写下来，用的是断断续续、上气不接下气的口语，仿佛还在当面讲给人听。同成千上万的人一样，他是钻下水道逃出老城的。", highlight_en: ["Old Town"], highlight_zh: ["老城"], status: "draft", fact_source: "https://pl.wikipedia.org/wiki/Pami%C4%99tnik_z_powstania_warszawskiego" },
  { id: "pl-pianista-s1", kind: "scene", book_id: "pl-pianista", place_ids: ["pl-umschlagplatz"], location: "August 1942", location_zh: "1942 年 8 月", text_en: "Szpilman, a pianist at Polish Radio, is driven to the Umschlagplatz with his parents, brother and two sisters. They wait all day in the heat; his father buys a single caramel and cuts it into six pieces. As the crowd is pushed towards the wagons a Jewish policeman pulls him out of the line by the collar. He never sees his family again, and lives in hiding in Warsaw until the Russians come.", text_zh: "什皮尔曼是波兰广播电台的钢琴师，他同父母、弟弟和两个姐妹一起被赶到转运广场。他们在酷热中等了一整天；父亲买了一块奶糖，切成六份。人群被推向车厢的时候，一个犹太警察揪着衣领把他从队伍里拽了出来。他从此再没见过家人，此后一直躲藏在华沙，直到苏军到来。", highlight_en: ["Umschlagplatz"], highlight_zh: ["转运广场"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Pianist_(memoir)" },
  { id: "pl-zdazyc-s1", kind: "scene", book_id: "pl-zdazyc", place_ids: ["pl-umschlagplatz"], location: "Throughout", location_zh: "全书", text_en: "Hanna Krall talks with Marek Edelman, the last surviving commander of the ghetto uprising and by then a cardiologist in Łódź. In the summer of 1942 he stood day after day at the gate of the Umschlagplatz as a hospital messenger, pulling out those who could be passed off as sick, and watched four hundred thousand people go by. He refuses to make the uprising more heroic than the walk to the wagons; his work on the cardiac ward, he says, is a race with God for a life.", text_zh: "汉娜·克拉尔同马雷克·埃德尔曼交谈；他是隔离区起义最后一位在世的指挥者，这时已是罗兹的心脏科医生。1942 年夏天，他以医院通信员的身份日复一日站在转运广场的门口，把能冒充病人的人拉出来，眼看着四十万人从面前走过。他不肯把起义说得比走向车厢更英勇；他说，他在心脏科病房里做的事，是在同上帝抢一条命。", highlight_en: ["Umschlagplatz"], highlight_zh: ["转运广场"], status: "draft", fact_source: "https://pl.wikipedia.org/wiki/Zd%C4%85%C5%BCy%C4%87_przed_Panem_Bogiem" },
  { id: "pl-mala-apokalipsa-s1", kind: "scene", book_id: "pl-mala-apokalipsa", place_ids: ["pl-pkin"], location: "Throughout", location_zh: "全书", text_en: "In the morning two friends from the opposition come to tell the narrator that it has been decided: at eight that evening he is to burn himself in front of the Palace of Culture, where the Party is in session. He spends the day crossing a Warsaw where bridges fall down, nobody knows the date and the country is about to join the Soviet Union, collecting his petrol and matches and looking for a reason. The book came out in the underground press.", text_zh: "早上，两个反对派的朋友来通知叙述者：事情已经定了，今晚八点他要在文化科学宫前自焚，党正在里面开会。他花了一天穿过华沙——桥在塌，没人知道今天是几号，国家就要并入苏联——一边去取汽油和火柴，一边找一个理由。这本书最初是由地下出版社印行的。", highlight_en: ["Palace of Culture"], highlight_zh: ["文化科学宫"], status: "draft", fact_source: "https://pl.wikipedia.org/wiki/Ma%C5%82a_apokalipsa" },
  { id: "pl-family-moskat-s1", kind: "scene", book_id: "pl-family-moskat", place_ids: ["pl-krochmalna"], location: "Throughout", location_zh: "全书", text_en: "The novel follows the household of the rich Warsaw patriarch Meshulam Moskat and the young man from the provinces, Asa Heshel Bannet, who marries into it, from before the First World War to September 1939: the Hasidic courtyards, the markets and prayer houses of streets like Krochmalna, the children who turn to Zionism, Communism or America. It ends with German bombs falling on the city.", text_zh: "小说写华沙富有的大家长梅舒拉姆·莫斯卡特一家，以及从外省来、后来娶了他家姑娘的青年阿萨·赫舍尔·班内特，从第一次世界大战前一直写到 1939 年 9 月：哈西德派的院落，克罗赫马尔纳街这类街道上的集市和祈祷所，转向犹太复国主义、共产主义或美国的下一代。结尾是德国人的炸弹落在城里。", highlight_en: ["Krochmalna"], highlight_zh: ["克罗赫马尔纳街"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Family_Moskat" },
  { id: "pl-treblinka-s1", kind: "scene", book_id: "pl-treblinka-hell", place_ids: ["pl-treblinka"], location: "Throughout", location_zh: "全文", text_en: "Grossman walks the reader along the route the victims took: the fake station with its painted clock and timetables, the square where families were parted, the 'road of no return' between fences of pine branches, the building with the gas chambers. He describes the revolt of August 1943, and ends on the sandy field itself, which gives up scraps of the dead underfoot.", text_zh: "格罗斯曼领着读者沿受害者走过的路走了一遍：画着钟面和时刻表的假车站，一家人被拆散的广场，两道松枝篱笆之间的“不归路”，设有毒气室的那座房子。他写了 1943 年 8 月的暴动，最后落在那片沙地本身：脚下的土里还不断翻出死者的零碎遗物。", highlight_en: ["station"], highlight_zh: ["车站"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Vasily_Grossman" },
  { id: "pl-schindler-s1", kind: "scene", book_id: "pl-schindler", place_ids: ["pl-fabryka-schindlera"], location: "Throughout", location_zh: "全书", text_en: "Keneally builds the book from the testimony of the survivors. Schindler, a Sudeten German on the make, arrives in Kraków in 1939, takes over a bankrupt enamel works and staffs it with cheap Jewish labour; by 1943 the factory in Lipowa Street has become a refuge whose owner bribes, drinks with and lies to the SS to keep his people off the transports, and at last buys them a place on the list for his new plant at Brünnlitz.", text_zh: "基尼利根据幸存者的证词写成此书。辛德勒是个一心想发财的苏台德德国人，1939 年来到克拉科夫，接手一家破产的搪瓷厂，雇用廉价的犹太劳工；到 1943 年，利波瓦街的这家工厂已成了避难所，老板靠行贿、陪酒和撒谎对付党卫军，让自己的人不被送上列车，最后又花钱把他们买进那份名单，带到布吕恩利茨的新厂。", highlight_en: ["Lipowa Street"], highlight_zh: ["利波瓦街"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Schindler%27s_Ark" },
  { id: "pl-borowski-s1", kind: "scene", book_id: "pl-pozegnanie-z-maria", place_ids: ["pl-auschwitz"], location: "'This Way for the Gas, Ladies and Gentlemen'", location_zh: "《女士们先生们，请进毒气室》", text_en: "A summer day at the Birkenau ramp. The narrator, a Polish political prisoner, joins the 'Canada' squad that unloads a transport of Jews; in return the squad keeps the food from the wagons. Train after train comes in; he carries out the dead infants, is sick, and goes back to work. Borowski gives the narrator his own first name and no excuses.", text_zh: "比克瑙站台上的一个夏日。叙述者是波兰政治犯，他跟着“加拿大”工作队去卸一车犹太人；作为报酬，工作队可以留下车厢里的食物。列车一趟接一趟开来；他把死去的婴儿抬出来，吐了，又回去接着干。博罗夫斯基让叙述者用了自己的名字，没有替他辩解一句。", highlight_en: ["Birkenau"], highlight_zh: ["比克瑙"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/This_Way_for_the_Gas,_Ladies_and_Gentlemen" },
  { id: "pl-czarny-ogrod-s1", kind: "scene", book_id: "pl-czarny-ogrod", place_ids: ["pl-nikiszowiec"], location: "Throughout", location_zh: "全书", text_en: "Szejnert, a reporter, follows the Giesche company's two model settlements from their founding: the garden village of Giszowiec and the brick blocks of Nikiszowiec. Through parish books, company files and family memories she tells what plebiscite, three uprisings, two wars and changing borders did to people who said of themselves only that they were from here.", text_zh: "记者出身的谢伊内特从建村写起，追踪吉舍公司的两处模范住宅区：花园式的吉绍维茨和砖楼成片的尼基绍维茨。她靠堂区登记册、公司档案和各家的回忆，讲述公民投票、三次起义、两场战争和一再变动的国界，给这些只说自己是“本地人”的人带来了什么。", highlight_en: ["Nikiszowiec"], highlight_zh: ["尼基绍维茨"], status: "draft", fact_source: "https://pl.wikipedia.org/wiki/Ma%C5%82gorzata_Szejnert" },
  { id: "pl-erste-polka-s1", kind: "scene", book_id: "pl-erste-polka", place_ids: ["pl-radiostacja"], location: "31 August 1939", location_zh: "1939 年 8 月 31 日", text_en: "One day in the border town, seen mostly from the Piontek household: Valeska, the piano teacher, is marrying off her daughter Irma; her husband lies ill in bed; her son Josel roams the town. German and the local Polish dialect mix in people's speech. In the evening some of them become witnesses of the staged raid on the radio station.", text_zh: "边境小城里的一天，主要从皮翁泰克一家的角度来看：钢琴教师瓦莱斯卡忙着操办女儿伊尔玛的婚礼；她的丈夫卧病在床；儿子约泽尔在城里游荡。人们说话时德语和当地的波兰方言混在一起。傍晚，他们当中有人成了那场伪造的广播电台袭击的目击者。", highlight_en: ["radio station"], highlight_zh: ["广播电台"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Horst_Bienek" },
  { id: "pl-weber-s1", kind: "scene", book_id: "pl-weber", place_ids: ["pl-pieszyce"], location: "Acts I and IV", location_zh: "第一幕、第四幕", text_en: "The play opens in the manufacturer Dreissiger's house at Peterswaldau, where the home weavers queue to hand in their cloth and have their pay docked. By Act IV they are in the street outside, singing the song of the 'bloody justice'; Dreissiger and his family slip away and the crowd goes through the house, breaking what it finds. The last act moves to Langenbielau and the soldiers' volley.", text_zh: "戏从彼得斯瓦尔道厂主德赖西格的家里开场：家庭织工排着队来交布，工钱被东扣西扣。到第四幕，他们已经站在门外的街上，唱着那首“血腥的审判”之歌；德赖西格一家溜走了，人群冲进宅子，见什么砸什么。最后一幕转到朗根比劳，军队开了枪。", highlight_en: ["Peterswaldau"], highlight_zh: ["彼得斯瓦尔道"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Weavers_(play)" },
  { id: "pl-empuzjon-s1", kind: "scene", book_id: "pl-empuzjon", place_ids: ["pl-sokolowsko"], location: "Throughout", location_zh: "全书", text_en: "Mieczysław Wojnicz, a student from Lwów, comes to Görbersdorf in September 1913 to be treated for consumption and lodges in a guesthouse for gentlemen. Every evening the lodgers drink the local liqueur and discourse on the inferiority of women; every November, he learns, a young man of the village is killed. Tokarczuk calls the book a health-resort horror story and writes it in the shadow of The Magic Mountain.", text_zh: "利沃夫来的大学生梅奇斯瓦夫·沃伊尼奇 1913 年 9 月到格贝尔斯多夫治肺病，住进一家只收男客的膳宿公寓。房客们每晚喝着当地的利口酒，高谈女人如何低劣；他又听说，每年十一月村里都有一个年轻男人被杀。托卡尔丘克管这本书叫“疗养地恐怖小说”，它是在《魔山》的影子里写成的。", highlight_en: ["Görbersdorf"], highlight_zh: ["格贝尔斯多夫"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Empusium" },
  { id: "pl-dom-dzienny-s1", kind: "scene", book_id: "pl-dom-dzienny", place_ids: ["pl-nowa-ruda"], location: "Throughout", location_zh: "全书", text_en: "The narrator and her husband move into a house in a valley outside Nowa Ruda, in land that was German until 1945. The book is made of what gathers there: the talk of her neighbour Marta, a wig-maker; dreams collected from the internet; recipes for mushrooms; the legend of the bearded saint Kummernis and of the monk who wrote her life; the story of the Germans who left and come back to look.", text_zh: "叙述者和丈夫搬进新鲁达城外山谷里的一所房子，这片土地 1945 年以前属于德国。全书由聚拢到这里的东西组成：做假发的邻居玛尔塔的闲谈，从互联网上收集来的梦，蘑菇菜谱，长胡子的圣女库梅尔尼斯的传说和为她写传的修士的故事，还有那些离开了又回来看一眼的德国人。", highlight_en: ["Nowa Ruda"], highlight_zh: ["新鲁达"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/House_of_Day,_House_of_Night" },
  { id: "pl-plug-s1", kind: "scene", book_id: "pl-plug", place_ids: ["pl-nowa-ruda"], location: "Throughout", location_zh: "全书", text_en: "Janina Duszejko, an elderly former engineer who teaches English and looks after the summer houses on a windy plateau by the Czech border, is woken one winter night: her neighbour, a poacher she calls Big Foot, lies dead with a deer bone in his throat. More hunters die. She writes to the police that the animals are taking revenge, casts horoscopes, and translates Blake.", text_zh: "雅尼娜·杜舍伊科上了年纪，从前是工程师，如今教英语，还替人照看捷克边境旁一处多风高地上的避暑房子。一个冬夜她被叫醒：她称作“大脚”的邻居、一个偷猎者死了，喉咙里卡着一块鹿骨。接着又有猎人死去。她写信告诉警察这是动物在复仇，一边排星盘，一边翻译布莱克。", highlight_en: ["plateau"], highlight_zh: ["高地"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Drive_Your_Plow_Over_the_Bones_of_the_Dead" },
  { id: "pl-breslau-s1", kind: "scene", book_id: "pl-smierc-w-breslau", place_ids: ["pl-wroclaw-glowny"], location: "Opening", location_zh: "开篇", text_en: "The investigation takes Eberhard Mock, a policeman with a taste for chess, Latin and brothels, through the Breslau of the first months of Nazi rule: the police headquarters, the freemasons he belongs to, the Gestapo who want a Jewish culprit. Krajewski gives every street its German name, and the city itself, which no longer exists under that name, is the book's real subject.", text_zh: "这桩案子领着埃伯哈德·莫克——一个爱下棋、爱拉丁文、也爱逛妓院的警察——走遍纳粹上台头几个月的布雷斯劳：警察总局，他所属的共济会，一心要找个犹太人顶罪的盖世太保。克拉耶夫斯基给每条街都用了德语旧名；这座已不再叫这个名字的城市，才是书真正的主角。", highlight_en: ["Breslau"], highlight_zh: ["布雷斯劳"], status: "draft", fact_source: "https://pl.wikipedia.org/wiki/%C5%9Amier%C4%87_w_Breslau" },
  { id: "pl-kindheitsmuster-s1", kind: "scene", book_id: "pl-kindheitsmuster", place_ids: ["pl-gorzow"], location: "Throughout", location_zh: "全书", text_en: "The narrator drives to the Polish town with her husband, brother and teenage daughter and walks its streets looking for the child she was, whom she can only call by another name, Nelly: the family grocery, the Hitler Youth meetings she loved, the night the synagogue burned, the trek west in 1945. The question the book keeps asking is how one became what one was.", text_zh: "叙述者同丈夫、弟弟和十几岁的女儿开车来到这座已属波兰的城市，在街上寻找当年的那个孩子——她只能用另一个名字“内莉”来称呼她：家里的杂货店，她曾经喜爱的希特勒青年团集会，犹太会堂被烧的那一夜，1945 年向西的逃难。全书反复追问的是：人是怎么变成当初那个样子的。", highlight_en: ["Polish town"], highlight_zh: ["这座已属波兰的城市"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Patterns_of_Childhood" },
  { id: "pl-effi-s1", kind: "scene", book_id: "effi-briest", place_ids: ["pl-swinoujscie"], location: "Chapters 6–22", location_zh: "第六至二十二章", text_en: "Effi, seventeen, arrives in Kessin as the wife of the district governor Innstetten. The town has a harbour, a pier, dunes and a wood, and a few consuls and a hunchbacked apothecary for society; their house has an upper room no one uses, a stuffed shark in the hall and the story of a Chinaman buried among the dunes. Here, bored and frightened, she lets Major Crampas ride beside her along the beach.", text_zh: "十七岁的艾菲作为县长殷士台顿的妻子来到凯辛。小城有港口、栈桥、沙丘和一片树林，社交圈里只有几位领事和一个驼背的药剂师；他们家楼上有间没人用的屋子，门厅里挂着鲨鱼标本，还有一个中国人葬在沙丘间的传说。就在这里，又闷又怕的她让克拉姆巴斯少校骑马陪她走在海滩上。", highlight_en: ["Kessin"], highlight_zh: ["凯辛"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Effi_Briest" },
  { id: "pl-blechtrommel-s1", kind: "scene", book_id: "pl-blechtrommel", place_ids: ["pl-poczta-polska"], location: "Book One, 'The Polish Post Office'", location_zh: "第一篇“波兰邮局”", text_en: "Oskar takes his broken drum to the caretaker Kobyella at the Polish Post Office to have it mended, and so is inside with his presumptive father Jan Bronski when the attack begins. In the room where the letters are stored the three of them play skat while shells hit the building, the dying Kobyella held upright with braces to make a third. Jan is taken out with the others and shot.", text_zh: "奥斯卡带着敲坏的鼓去波兰邮局找看门人科比埃拉修理，于是进攻开始时，他正同他那位可能的生父扬·布朗斯基一起待在楼里。炮弹打在楼上，他们三个在存放信件的房间里玩斯卡特牌，垂死的科比埃拉被人用背带捆着坐直，好凑成三家。扬后来同其他人一起被押出去枪毙了。", highlight_en: ["Polish Post Office"], highlight_zh: ["波兰邮局"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Tin_Drum" },
  { id: "pl-blechtrommel-s2", kind: "scene", book_id: "pl-blechtrommel", place_ids: ["pl-wrzeszcz"], location: "Book One", location_zh: "第一篇", text_en: "Oskar Matzerath is born in Langfuhr, in the flat behind his parents' grocery in Labesweg, under two sixty-watt bulbs. On his third birthday he is given a tin drum and decides to stop growing; from the cellar steps, the courtyard and the tram to the city he watches the suburb's grocers, greengrocers and bakers turn into Nazis.", text_zh: "奥斯卡·马策拉特出生在朗富尔，拉贝斯路父母杂货店后面的住房里，头顶是两只六十瓦的灯泡。三岁生日那天他得到一面铁皮鼓，决定不再长高；他在地窖的台阶上、院子里和进城的电车上，看着这片郊区的杂货商、菜贩和面包师一个个变成纳粹。", highlight_en: ["Langfuhr"], highlight_zh: ["朗富尔"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Tin_Drum" },
  { id: "pl-weiser-s1", kind: "scene", book_id: "pl-weiser", place_ids: ["pl-wrzeszcz"], location: "Summer 1957", location_zh: "1957 年夏天", text_en: "A hot summer; fish are dying in the bay and the priest preaches punishment. The narrator and his friends fall under the spell of a thin Jewish boy, Dawid Weiser, who tames a panther at the Oliwa zoo, plays football like a master and sets off explosions in the hollow behind the shooting range. After the last one he and the girl Elka are gone. Years later the narrator is still being questioned, by the school and by himself.", text_zh: "一个炎热的夏天；海湾里的鱼成片死去，神父在布道时说这是惩罚。叙述者和伙伴们被一个瘦瘦的犹太男孩达维德·魏泽尔迷住了：他在奥利瓦动物园驯服了一头黑豹，踢起球来像个行家，还在靶场后面的洼地里引爆炸药。最后一次爆炸之后，他和女孩埃尔卡都不见了。多年以后叙述者仍在受盘问——先是学校问他，后来是他自己问自己。", highlight_en: ["Oliwa"], highlight_zh: ["奥利瓦"], status: "draft", fact_source: "https://pl.wikipedia.org/wiki/Weiser_Dawidek" },
  { id: "pl-hanemann-s1", kind: "scene", book_id: "pl-hanemann", place_ids: ["pl-oliwa"], location: "Throughout", location_zh: "全书", text_en: "Hanemann, a professor of anatomy in Danzig, gives up his chair after the woman he loves drowns when an excursion steamer sinks, and when the Germans flee in 1945 he lets the last ship go without him. The narrator, a boy whose Polish parents have been given the flat below, tells of the silent German upstairs and of the things the departed left behind: china, linen, door handles, a way of living.", text_zh: "哈内曼是但泽的解剖学教授。他爱的女人在一艘游船沉没时淹死了，他从此放弃教席；1945 年德国人逃离的时候，他任凭最后一班船开走而没有上去。叙述者是个男孩，他的波兰父母分到了楼下的那套房子；他讲的是楼上那个沉默的德国人，还有离开的人留下的东西：瓷器，床单桌布，门把手，一种过日子的方式。", highlight_en: ["Danzig"], highlight_zh: ["但泽"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Stefan_Chwin" },
  { id: "pl-westerplatte-s1", kind: "scene", book_id: "pl-westerplatte-piesn", place_ids: ["pl-westerplatte"], location: "Whole poem", location_zh: "全诗", text_en: "A short ballad written in the first weeks of the war. When their days are fulfilled and it is time to die in summer, the soldiers of Westerplatte march off to heaven in ranks; the summer is fine, heather is in flower in the heavenly meadows, and they promise to come down again to Warsaw when the cold winds blow. Gałczyński himself was taken prisoner that September.", text_zh: "战争头几个星期写成的一首短歌谣。大限已到，该在夏天死去的时候，韦斯特普拉特的士兵们列着队向天堂走去；那个夏天很美，天上的草地里石楠开着花，他们许诺等寒风吹起时再下来回到华沙。加乌琴斯基本人就在那个九月当了俘虏。", highlight_en: ["Westerplatte"], highlight_zh: ["韦斯特普拉特"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Konstanty_Ildefons_Ga%C5%82czy%C5%84ski" },
  { id: "pl-szosta-klepka-s1", kind: "scene", book_id: "pl-szosta-klepka", place_ids: ["pl-jezyce"], location: "Throughout", location_zh: "全书", text_en: "The first of the Jeżyce books belongs to the Żak family, crowded into one flat of an old tenement: Celestyna, called Cesia, a schoolgirl sure that she is plain and dull, her beautiful elder sister Julia, a father everyone calls Żaczek, a mother busy with her own work, a grandfather, an aunt and little Bobcio. Over a school year of homework and first love she finds out otherwise. The Borejkos, who take over the series, arrive in a later volume.", text_zh: "“耶日采记”的第一本写的是挤在一幢老公寓某一套房子里的扎克一家：中学生采莱斯蒂娜（小名采霞）认定自己又平凡又乏味，她有个漂亮的姐姐尤利娅，一个人人都叫他“扎切克”的爸爸，一个忙着自己工作的妈妈，还有爷爷、姑姑和小博布乔。在做功课、初次恋爱的那个学年里，她发现事情并非如此。后来成为整套书主角的博雷伊科一家，要到后面的一本才登场。", highlight_en: ["Jeżyce"], highlight_zh: ["耶日采"], status: "draft", fact_source: "https://pl.wikipedia.org/wiki/Sz%C3%B3sta_klepka" },
  { id: "pl-noce-i-dnie-s1", kind: "scene", book_id: "pl-noce-i-dnie", place_ids: ["pl-kalisz"], location: "Throughout", location_zh: "全书", text_en: "Barbara Ostrzeńska, a girl from an impoverished gentry family in Kaliniec, marries Bogumił Niechcic, a veteran of the 1863 rising, without loving him, and spends thirty years beside him on the estates he manages, restless where he is content. After his death she moves back to town. When the Germans shell Kaliniec in 1914 she drives out of the burning streets in a cart, looking for her children.", text_zh: "芭尔芭拉·奥斯特任斯卡出身卡利涅茨一个破落的乡绅家庭，她并不爱博古米乌·涅赫齐茨——一个参加过 1863 年起义的老兵——却嫁给了他，在他替人经管的庄园里陪他过了三十年；他安于现状，她总是心神不定。丈夫死后她搬回城里。1914 年德军炮轰卡利涅茨，她坐着一辆大车驶出燃烧的街道，去找自己的孩子。", highlight_en: ["Kaliniec"], highlight_zh: ["卡利涅茨"], status: "draft", fact_source: "https://pl.wikipedia.org/wiki/Noce_i_dnie_(powie%C5%9B%C4%87)" },
  { id: "pl-jakob-s1", kind: "scene", book_id: "pl-jakob", place_ids: ["pl-radegast"], location: "Throughout", location_zh: "全书", text_en: "Jakob Heym, who once sold potato pancakes, is sent to the German guard post for being out after curfew and there overhears a radio report that the Russians are near. To make a friend believe him he says he has a radio, which in the ghetto means death. People stop killing themselves; so day after day he has to invent the news. The narrator, a survivor, offers two endings, and says which one happened.", text_zh: "雅各布·海姆从前是卖土豆饼的。他因为宵禁后还在街上，被打发去德国岗哨，在那里偷听到一条广播：俄国人已经不远了。为了让一个朋友相信，他说自己有一台收音机——在隔离区里这是死罪。人们不再自杀了；于是他只好一天接一天地编造新闻。叙述者是个幸存者，他给出了两个结局，并且说明了哪一个才是真的。", highlight_en: ["ghetto"], highlight_zh: ["隔离区"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Jacob_the_Liar" },
  { id: "pl-widnokrag-s1", kind: "scene", book_id: "pl-widnokrag", place_ids: ["pl-sandomierz"], location: "Throughout", location_zh: "全书", text_en: "Piotr, grown up, turns over the photographs of his childhood: the village of his mother's family during the war, and then the town on the hill, where his father is slowly dying. The long stairs between the upper town and the suburb by the river are climbed again and again; a lost shoe, a dog, a first cigarette each open a whole chapter.", text_zh: "已经长大的彼得翻看着童年的照片：战时母亲娘家所在的村子，然后是山坡上的那座城；父亲在城里慢慢地走向死亡。上城和河边郊区之间那道长长的台阶被一遍遍地爬过；一只丢了的鞋、一条狗、第一支烟，各自引出整整一章。", highlight_en: ["town on the hill"], highlight_zh: ["山坡上的那座城"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Wies%C5%82aw_My%C5%9Bliwski" },
  { id: "pl-magician-s1", kind: "scene", book_id: "pl-magician-lublin", place_ids: ["pl-lublin"], location: "Chapter 1", location_zh: "第一章", text_en: "Yasha Mazur, tightrope walker, lock-picker and conjurer, comes home to Lublin for the holidays, to his pious wife Esther and his house with its horses, monkey and crow. He does not keep the commandments; he is known in every tavern and has a woman in every town on the road to Warsaw. From here he sets out towards the city, a Christian widow and a burglary that will end with him walled up in a cell in his own yard.", text_zh: "雅夏·马祖尔是走钢丝的、开锁的、变戏法的；他回卢布林过节，回到虔诚的妻子埃丝特身边，回到养着马、猴子和乌鸦的家里。他不守诫命，各家酒馆都认得他，去华沙的路上每个镇子里都有他的女人。他从这里出发，走向那座城市，走向一位信基督教的寡妇和一桩入室行窃——最后他把自己砌进了自家院子里的一间小屋。", highlight_en: ["Lublin"], highlight_zh: ["卢布林"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/The_Magician_of_Lublin_(novel)" },
  { id: "pl-poemat-s1", kind: "scene", book_id: "pl-poemat-lublin", place_ids: ["pl-lublin"], location: "Throughout", location_zh: "全诗", text_en: "A wanderer comes back to his native town at dusk and walks through it by night under a summer moon: through the old town, past the castle and down the lanes of the Jewish quarter. Each poem of the cycle is one stop on the walk. Czechowicz wrote it as a text for radio.", text_zh: "一个漂泊者在黄昏回到故乡，在夏夜的月光下穿城而行：穿过老城，经过城堡，走进犹太区的小巷。组诗里的每一首是这次夜行的一站。切霍维奇是把它当作广播稿来写的。", highlight_en: ["old town"], highlight_zh: ["老城"], status: "draft", fact_source: "https://pl.wikipedia.org/wiki/J%C3%B3zef_Czechowicz_(poeta)" },
  { id: "pl-dwa-ksiezyce-s1", kind: "scene", book_id: "pl-dwa-ksiezyce", place_ids: ["pl-kazimierz-dolny"], location: "Throughout", location_zh: "全书", text_en: "Linked stories of one small town in which two worlds live side by side and hardly look at each other: the locals, Polish and Jewish, boatmen, shopkeepers, beggars and a blind man who knows every stone; and the summer people, painters and their models from Warsaw, for whom the market square is scenery.", text_zh: "一组互相勾连的短篇，写的是同一座小城：两个世界在这里并排过日子，彼此几乎不看一眼——一边是本地人，波兰人和犹太人，船夫、小店主、乞丐，还有一个认得每块石头的盲人；另一边是来消夏的人，华沙来的画家和他们的模特，在他们眼里集市广场只是一道风景。", highlight_en: ["small town"], highlight_zh: ["小城"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Maria_Kuncewiczowa" },
  { id: "pl-satan-s1", kind: "scene", book_id: "pl-satan-goray", place_ids: ["pl-goraj"], location: "Throughout", location_zh: "全书", text_en: "Goray, a small town lost among the hills at the back of beyond, has been half emptied by Khmelnytsky's Cossacks. Seventeen years later messengers bring word that the Messiah has appeared; the old rabbi who resists is driven out, fasts turn into feasts, laws are thrown over, and the prophetess of the new age is Rechele, a sick girl in whom, by the end, a dybbuk speaks.", text_zh: "戈拉伊这座深藏在群山之中、仿佛在世界尽头的小镇，被赫梅利尼茨基的哥萨克洗劫得只剩一半人。十七年后，信使带来弥赛亚已经显现的消息；抵制这股风潮的老拉比被赶走，斋戒变成了宴饮，律法被抛到一边，新时代的女先知是病弱的姑娘蕾海莱——到最后，是一个附体的恶灵借她的嘴说话。", highlight_en: ["Goray"], highlight_zh: ["戈拉伊"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Satan_in_Goray" },
  { id: "pl-dukla-s1", kind: "scene", book_id: "pl-dukla", place_ids: ["pl-dukla"], location: "Title piece", location_zh: "同名长篇散文", text_en: "Stasiuk drives or walks into the little town again and again, at different hours and seasons, to watch what light does to it: to the empty market square, the bus stop, the tomb of Maria Amalia Mniszech in the parish church with her marble slippers and lace. Memories of a boyhood summer and a girl dancing surface and sink. Nothing happens; the book is about looking.", text_zh: "斯塔休克一次次开车或步行来到这座小城，挑不同的钟点、不同的季节，看光线怎样落在它身上：空荡荡的集市广场，汽车站，堂区教堂里玛丽亚·阿玛利亚·姆尼舍赫的陵墓——大理石雕出的便鞋和蕾丝。少年时代某个夏天和一个跳舞女孩的记忆浮上来，又沉下去。什么也没有发生；这是一本关于“看”的书。", highlight_en: ["little town"], highlight_zh: ["小城"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Andrzej_Stasiuk" },
  { id: "pl-zemsta-s1", kind: "scene", book_id: "pl-zemsta", place_ids: ["pl-odrzykon"], location: "Throughout", location_zh: "全剧", text_en: "Two neighbours share one castle and hate each other: the hot-headed Cupbearer Raptusiewicz and the soft-spoken, implacable Notary Milczek. When the Notary hires masons to mend the wall between their halves, the Cupbearer sends his men to drive them off. Each plots a marriage to spite the other, the braggart Papkin carries messages and makes his will, and the young lovers from the two sides are married before either old man can stop it.", text_zh: "两个邻居共住一座城堡，彼此恨之入骨：火暴脾气的司酒官拉普图谢维奇，和说话轻声细气却毫不让步的公证人米尔切克。公证人雇泥瓦匠修两家之间的那堵墙，司酒官就派手下把他们轰走。两人各自盘算着一门亲事来气对方，吹牛大王帕普金来回传话，还立下了遗嘱；两家的一对年轻恋人赶在两个老头来得及阻拦之前成了亲。", highlight_en: ["castle"], highlight_zh: ["城堡"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Zemsta" },
  // —— 11-26: Lithuanian books set here (tools/content/batches/add_lt1.py) ——
  { id: "pl-dm-1", kind: "scene", book_id: "dievu-miskas", place_ids: ["pl-stutthof"], location: "The book as a whole", location_zh: "全书", text_en: "In March 1943 the German occupiers sent the Lithuanian writer Balys Sruoga, with forty-seven other Lithuanian intellectuals, to the Stutthof concentration camp east of Danzig, in a campaign against possible anti-Nazi agitation in occupied Lithuania. Forest of the Gods is his memoir of the camp, told with sarcastic irony and black humour, the beatings of prisoners and the dragging of corpses included; the critic Algis Kalėda saw this as the only way to fence oneself off from a coldly rational system for destroying people. Sruoga wrote it in a few months in the summer of 1945, recovering in the Birštonas sanatorium after his return; Soviet censors stopped it, and it was first published in 1957, ten years after his death. Algimantas Puipa filmed it in 2005.", text_zh: "1943 年 3 月，德国占领当局以防范被占领的立陶宛出现反纳粹鼓动为名，把立陶宛作家巴利斯·斯鲁奥加和另外 47 名立陶宛知识分子送进但泽以东的施图特霍夫集中营。《众神之林》是他写这座集中营的回忆录，通篇是尖刻的反讽和黑色幽默，连毒打囚犯、拖运尸体的场面也不例外；评论家阿尔吉斯·卡列达认为，这是在一套冷静算计的灭绝人的系统面前，唯一能让人稍稍隔开自己的办法。1945 年夏天，斯鲁奥加回国后在比尔什托纳斯疗养院养病，只用几个月就写完了这本书；苏联审查不许出版，直到 1957 年、他去世十年后才第一次印出来。2005 年阿尔吉曼塔斯·普伊帕把它拍成了电影。", highlight_en: ["Stutthof"], highlight_zh: ["施图特霍夫"], status: "draft", fact_source: "https://en.wikipedia.org/wiki/Balys_Sruoga; https://lt.wikipedia.org/wiki/Dievų_miškas; https://en.wikipedia.org/wiki/Stutthof_concentration_camp" }
];
